<!doctype html>
<html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>CAIXA Loterias | Iniciativas Estratégicas</title><link rel="stylesheet" href="/assets/css/styles.css">
<script src="/assets/js/dataStore.js" defer></script><script src="/assets/js/databaseService.js" defer></script><script src="/assets/js/auth.js" defer></script><script src="/assets/js/action-feedback.js" defer></script><script src="/assets/js/iniciativas.js" defer></script><script src="/assets/js/app.js" defer></script></head>
<body data-page="iniciativas"><div class="app-shell"><header id="appHeader" class="topbar"></header><nav id="appNav" class="sidebar"></nav><main class="content">
<section class="page-heading"><p class="eyebrow">Execução estratégica</p><h1>Iniciativas Estratégicas</h1><p>Cadastro, acompanhamento trimestral e evidências das iniciativas.</p></section>
<nav class="module-tabs" aria-label="Áreas de iniciativas"><a class="active" href="/iniciativas">Acompanhamentos</a><a href="/iniciativas/homologacao">Homologação</a><a href="/iniciativas/consolidacao-ca">Consolidação CA</a></nav>
<section id="initiativeAdminActions" class="panel panel-actions" hidden><button id="newInitiativeButton" class="primary-action" type="button">Nova iniciativa</button><label>Gerar acompanhamentos do ano <input id="generationYear" type="number" min="1900" max="9999"></label><button id="generateYearButton" class="secondary-action" type="button">Gerar</button></section>
<section class="filters" aria-label="Filtros"><label>Ano <input data-initiative-filter="ano" type="number"></label><label>Trimestre <select data-initiative-filter="trimestre"><option value="">Todos</option><option>1TRI</option><option>2TRI</option><option>3TRI</option><option>4TRI</option></select></label><label>Pilar <input data-initiative-filter="pilar"></label><label>Unidade <input data-initiative-filter="unidade"></label><label>Diretoria <input data-initiative-filter="diretoria"></label><label>Status <select data-initiative-filter="statusFluxo"><option value="">Todos</option><option>NAO_INICIADO</option><option>EM_PREENCHIMENTO</option><option>ENVIADO_HOMOLOGACAO</option><option>DEVOLVIDO_AJUSTE</option><option>HOMOLOGADO</option><option>REABERTO</option></select></label><button id="initiativeFilterButton" class="secondary-action" type="button">Filtrar</button></section>
<section class="panel"><div id="initiativeMessage" class="action-feedback" hidden></div><div class="table-wrap"><table><thead><tr><th>Código</th><th>Pilar</th><th>Iniciativa</th><th>Unidade</th><th>Período</th><th>Status da iniciativa</th><th>Status do acompanhamento</th><th>Ações</th></tr></thead><tbody id="initiativesTable"></tbody></table></div></section>
<section id="initiativeMasterPanel" class="panel detail-panel" hidden><div class="detail-header"><div><p class="eyebrow">Cadastro mestre</p><h2 id="initiativeMasterTitle">Nova iniciativa</h2></div><button type="button" class="secondary-action" data-close-panel="initiativeMasterPanel">Voltar</button></div><form id="initiativeMasterForm" class="editor-form"><input id="initiativeMasterId" type="hidden"><label>Código<input id="initiativeCode" readonly placeholder="Gerado ao salvar"></label><label>Plano<input id="initiativePlan" required maxlength="255"></label><label>Pilar<input id="initiativePillar" required maxlength="255"></label><label>Título Executivo<input id="initiativeTitle" required maxlength="255"></label><label class="full-span">Iniciativa Estratégica oficial<textarea id="initiativeDescription" required rows="4"></textarea></label><label class="full-span">Objetivo da iniciativa<textarea id="initiativeObjective" required rows="3"></textarea></label><label>Unidade responsável<input id="initiativeUnit" required maxlength="255"></label><label>Diretoria responsável<input id="initiativeBoard" required maxlength="255"></label><label>Ano de início<input id="initiativeStartYear" type="number" min="1900" max="9999" required></label><label>Trimestre de início<select id="initiativeStartQuarter"><option>1TRI</option><option>2TRI</option><option>3TRI</option><option>4TRI</option></select></label><label>Previsão de conclusão<input id="initiativeDueDate" type="date"></label><label class="checkbox-line"><input id="initiativeRequiresEvidence" type="checkbox"> Exige evidência</label><label id="initiativeReasonWrapper" class="full-span" hidden>Justificativa para alteração sensível<textarea id="initiativeReason" rows="3"></textarea></label><div class="form-actions full-span"><button class="primary-action" type="submit">Salvar cadastro</button><button id="initiativeToggleButton" class="secondary-action" type="button" hidden></button></div></form></section>
<section id="initiativeTrackingPanel" class="panel detail-panel" hidden><div class="detail-header"><div><p class="eyebrow">Acompanhamento trimestral</p><h2 id="trackingTitle"></h2></div><span id="trackingStatus" class="badge info"></span></div><div id="trackingSnapshot" class="detail-grid"></div><form id="trackingForm" class="editor-form"><label>Status da iniciativa<select id="trackingInitiativeStatus"><option value="">Selecione</option><option value="NAO_INICIADA">Não iniciada</option><option value="EM_ANDAMENTO">Em andamento</option><option value="CONCLUIDA">Concluída</option><option value="SUSPENSA">Suspensa</option><option value="CANCELADA">Cancelada</option></select></label><label class="full-span">Andamento da Unidade<textarea id="trackingProgress" rows="5"></textarea></label><label class="full-span">Referência documental / link<input id="trackingEvidenceReference" maxlength="2000"></label><div id="initiativeItems"></div><section class="evidence-section full-span"><h3>Evidências</h3><div class="evidence-upload-grid"><label>Arquivo<input id="initiativeEvidenceFile" type="file" accept=".pdf,.jpg,.jpeg,.png,.xls,.xlsx,.doc,.docx"></label><label>Descrição<input id="initiativeEvidenceDescription" maxlength="500"></label><button id="initiativeEvidenceUpload" class="secondary-action" type="button">Adicionar arquivo</button></div><div id="initiativeEvidenceList" class="evidence-list"></div></section><section class="full-span"><h3>Histórico do fluxo</h3><div id="initiativeHistory" class="history-list"></div></section><label id="trackingReopenReasonWrapper" class="full-span" hidden>Justificativa da reabertura<textarea id="trackingReopenReason" rows="3"></textarea></label><div class="form-actions action-feedback-bar full-span"><div id="trackingFeedback" class="action-feedback" hidden></div><button id="trackingSave" class="primary-action" type="button">Salvar rascunho</button><button id="trackingSubmit" class="secondary-action" type="button">Enviar para homologação</button><button id="trackingReopen" class="secondary-action" type="button" hidden>Reabrir para edição</button><button class="secondary-action" type="button" data-close-panel="initiativeTrackingPanel">Voltar</button></div></form></section>
</main></div></body></html>
